package net.mandomc.verification;
import java.util.*;import java.nio.file.*;import org.bukkit.*;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.*;import org.bukkit.plugin.java.JavaPlugin;import net.mandomc.bootstrap.MandoPlugin;import net.mandomc.gameplay.dungeon.*;
public final class JabbaRecoveryProbe extends JavaPlugin {
 MandoPlugin p;JabbaEvent event;Path dir,journal;int checks;YamlConfiguration state;
 public void onEnable(){Bukkit.getScheduler().runTaskLater(this,()->{try{run();}catch(Throwable t){getLogger().log(java.util.logging.Level.SEVERE,"RECOVERY FAILED",t);write("FAILED.txt",t.toString());Bukkit.shutdown();}},120);}
 void check(boolean ok,String m){if(!ok)throw new AssertionError(m);checks++;}
 void write(String name,String value){try{Files.createDirectories(getDataFolder().toPath());Files.writeString(getDataFolder().toPath().resolve(name),value);}catch(Exception e){throw new RuntimeException(e);}}
 void run()throws Exception{
 p=(MandoPlugin)Bukkit.getPluginManager().getPlugin("MandoMC");p.events().stop(false);event=(JabbaEvent)p.events().event("jabba");dir=getDataFolder().toPath();Files.createDirectories(dir);state=YamlConfiguration.loadConfiguration(dir.resolve("state.yml").toFile());journal=p.getDataFolder().toPath().resolve("jabba/palace-run.yml");int stage=state.getInt("stage",0);
 if(stage>0){var w=Bukkit.getWorld(NamespacedKey.fromString(state.getString("world")));for(String line:state.getStringList("cleanup")){var a=line.split("\\|",2);check(JabbaSettings.Pos.parse(a[0]).location(w).getBlock().getBlockData().getAsString().equals(Bukkit.createBlockData(a[1]).getAsString()),"restored after restart "+line);}for(int x=state.getInt("min-x");x<=state.getInt("max-x");x++)for(int z=state.getInt("min-z");z<=state.getInt("max-z");z++)w.getChunkAt(x,z);check(w.getEntities().stream().noneMatch(e->e.getScoreboardTags().contains("mandomc_jabba_palace")||e.getScoreboardTags().contains("mandomc_jabba_gate_palace")),"interrupted entities/panels cleared");}
 if(stage==0){
 var c=YamlConfiguration.loadConfiguration(dir.resolve("old-event.yml").toFile());var old=JabbaSettings.read(c);var w=Bukkit.getWorld(NamespacedKey.minecraft("tatooine"));var gates=new NativeGates(p,w,old,dir.resolve("old-doors.yml").toFile());List<String>plan=new ArrayList<>(gates.resetPlan());for(var r:old.rooms())for(var chest:r.chests())plan.add(chest.pos().key()+"|minecraft:air");gates.close();fixture(w,plan,1);return;
 }
 if(stage==1){
 check(event.settings().world().equals("minecraft:tatooine_review"),"legacy cleanup did not change official event world");check(p.events().start("jabba"),"new event starts after oldworld journal recovery");Bukkit.getScheduler().runTaskLater(this,()->{try{var saved=YamlConfiguration.loadConfiguration(journal.toFile());check(saved.getString("world").equals("minecraft:tatooine_review"),"new checkpoint targets new planet");var plan=saved.getStringList("cleanup");p.events().stop(false);fixture(Bukkit.getWorld(NamespacedKey.minecraft("tatooine_review")),plan,2);}catch(Throwable t){write("FAILED.txt",t.toString());Bukkit.shutdown();}},40);return;
 }
 check(!event.running(),"recovered operation idle");check(p.events().start("jabba"),"new run starts after newworld recovery");check(event.cachesRemaining()==22,"fresh22caches");p.events().stop(false);write("PASSED.txt",(state.getInt("checks")+checks)+" restart assertions; oldworld cleanup and newworld interruption recover with exact blocks/entities, then new operation starts");Bukkit.shutdown();
 }
 void fixture(World world,List<String>plan,int next)throws Exception{
 var c=new YamlConfiguration();c.set("world",world.getKey().toString());c.set("cleanup",plan);var zombie=world.spawn(new Location(world,world.getKey().getKey().equals("tatooine")?1701.5:166.5,world.getKey().getKey().equals("tatooine")?102:122,world.getKey().getKey().equals("tatooine")?2201.5:134.5),Zombie.class);zombie.setPersistent(true);zombie.setRemoveWhenFarAway(false);zombie.setAI(false);zombie.addScoreboardTag("mandomc_jabba_palace");c.set("entities",List.of(zombie.getUniqueId().toString()));c.save(journal.toFile());
 int minX=Integer.MAX_VALUE,maxX=Integer.MIN_VALUE,minZ=Integer.MAX_VALUE,maxZ=Integer.MIN_VALUE;int changed=0;for(String line:plan){var a=line.split("\\|",2);var pos=JabbaSettings.Pos.parse(a[0]);var b=pos.location(world).getBlock();minX=Math.min(minX,b.getChunk().getX());maxX=Math.max(maxX,b.getChunk().getX());minZ=Math.min(minZ,b.getChunk().getZ());maxZ=Math.max(maxZ,b.getChunk().getZ());if(changed++%11==0)b.setType(Material.AIR,false);}
 var cache=JabbaSettings.Pos.parse(plan.getLast().split("\\|",2)[0]);cache.location(world).getBlock().setType(Material.CHEST,false);state.set("stage",next);state.set("world",world.getKey().toString());state.set("cleanup",plan);state.set("checks",state.getInt("checks")+checks);state.set("min-x",minX);state.set("max-x",maxX);state.set("min-z",minZ);state.set("max-z",maxZ);state.save(dir.resolve("state.yml").toFile());world.save();write("STAGE_"+next+".txt","Private interrupted state saved");Bukkit.shutdown();
 }
}
